INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺元年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/jiuwudaishi-112-october-relief/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺元年十月，段落 jiu-wudaishi-205deb4a7860-p002666；已核上下文及传主，纸本及异文待核。", "id": "9a1a2961-4883-598d-a352-d2ece374f11f"}, {"title": "宋史·卷261·列传二十·陈思让传·虒亭战事", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/songshi-261-siting-battle/source.txt", "note": "《宋史》卷261·列传二十·陈思让传·虒亭战事，段落 songshi-9c6e46fee832-p058037；已核上下文及传主，纸本及异文待核。", "id": "69dda249-99cc-5cf2-88dc-87fe594abb5d"}, {"title": "资治通鉴·卷290·广顺元年·十月至十一月入楚与晋州战事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/tongjian-290-951-october-november/source.txt", "note": "《资治通鉴》卷290·广顺元年·十月至十一月入楚与晋州战事，段落 zizhi-tongjian-a63549944a71-p003447；已核上下文及传主，纸本及异文待核。", "id": "2eb03298-ebb5-51db-b6b7-6e62af86252d"}, {"title": "新五代史·卷32·死节传·刘仁赡早年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/xinwudaishi-032-liu-renshan/source.txt", "note": "《新五代史》卷32·死节传·刘仁赡早年，段落 xin-wudaishi-b08f244b9241-p001161；已核上下文及传主，纸本及异文待核。", "id": "27bb679d-64ae-5a63-b0ef-ff754e0ea63f"}, {"title": "新五代史·卷62·南唐世家·保大九年入楚", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/xinwudaishi-062-chu-conquest/source.txt", "note": "《新五代史》卷62·南唐世家·保大九年入楚，段落 xin-wudaishi-b08f244b9241-p003146；已核上下文及传主，纸本及异文待核。", "id": "6a9c9e70-dbf0-5722-b8e9-19cc77f6cb1f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "陈思让", "aliases": ["陳思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋作坊使，幽州人。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋军监军。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "59feec41-432b-5d18-829a-46def9523238"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "张仁谦", "aliases": ["張仁謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。《宋史》陈思让传记他于951年与陈思让、向训等率军在虒亭西迎战北汉。生卒年未载。", "biography": null, "status": "draft", "id": "3c908e76-fb6b-5120-a480-5eada2c5ad92"}, {"name": "王璠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉偏将。《宋史》记951年虒亭交战中被陈思让等俘获。出生、死亡年份未载。", "biography": null, "status": "draft", "id": "57b54bf3-e528-5a09-91ad-1ced2300723a"}, {"name": "曹海金", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉偏将。《宋史》记951年虒亭交战中被陈思让等俘获。出生、死亡年份未载。", "biography": null, "status": "draft", "id": "2a8dd3c8-4691-5501-81c5-3ac6fe4bc65b"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：拓跋恒，楚国仆射获任者。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}, {"name": "萧禹厥", "aliases": ["蕭禹厥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹彰国节度使。951年奉命率奚、契丹五万军队与北汉会合进攻后周。其他同音姓名对应及生卒年待核。", "biography": null, "status": "draft", "id": "e1c51dfb-2b2f-536a-add4-53d5aeb00144"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "王万敢", "aliases": ["王萬敢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉密州刺史。949年十二月攻击南唐海州获水镇；《旧五代史》次年正月也载他在海州方向的奏报，镇名作荻水，地名及是否同次行动仍待校核。生卒年未载。", "biography": null, "status": "draft", "id": "0e0fb3d0-08be-5b24-8bc6-9cb76e19259a"}, {"name": "史彦超（后周将领）", "aliases": ["史彦超", "史彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后周龙捷都指挥使。951年与王万敢、何徽防守晋州，抵抗北汉、契丹军。尚不与其他政权的同名将领合并，生卒年未录全。", "biography": null, "status": "draft", "id": "541b4701-1443-5a49-a822-4dc8d508ecee"}, {"name": "何徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周虎捷指挥使。951年与王万敢、史彦超共同抵御北汉、契丹对晋州的进攻。生卒年未载。", "biography": null, "status": "draft", "id": "2982109b-18cc-561f-9927-a98ba7b7f5e6"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "刘金", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：刘金。", "biography": null, "status": "draft", "id": "f52d5f3e-f0ed-5141-b2d1-7c46f0142156"}, {"name": "高远（南唐起居郎）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "幽州人，南唐起居郎。951年百官庆贺取湖南时，他认为取楚容易、守楚困难。未与其他年代同名人物合并，生卒年未载。", "biography": null, "status": "draft", "id": "1f645136-e01d-56f6-b3ff-a9e5d6f229e4"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "申师厚", "aliases": ["申師厚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王峻的故交，曾为兖州牙将，失去职务后生活困顿。951年经王峻推荐任河西节度使，《旧五代史》还记任职前先授左卫将军。生卒年未载。", "biography": null, "status": "draft", "id": "726c5795-d4be-50c7-b995-7c1e7267c2bf"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "折逋嘉施", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "凉州留后。951年向后周朝廷上表请求派来统帅，后周随后任命申师厚为河西节度使。生卒年未载。", "biography": null, "status": "draft", "id": "2083b5ce-a582-5425-8977-3324bcf9ace6"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
